class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int T = in.nextInt();
        while (T-- > 0){
            int n = in.nextInt();
            int x = in.nextInt();
            int k = in.nextInt();
            if(k == n+1){
                System.out.println(x);
                continue;
            }
            int count = n-k+1;
            while (count-- > 0){
                x = x % (n--);
            }
            System.out.println(x);
        }
    }

}
